      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/12~15) 7세 유치원~ 남녀 초등학생(1-3학년) 대면 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.14. 12:30\n조회 85\n구독\n10/12~15) 7세 유치원~ 남녀 초등학생(1-3학년) 대면 좌담회\n7세 유치원~ 남녀 초1.2.3 인원이 많이 부족합니다.\n신청하신분은 재신청 안하셔도 됩니다\n남자 여자 어린이 유치원(7세) ~ 초등학교 전학년 대상\n> 일시:10/12(월)-10/15(목)일 중 하루 / 3시,5시,7시\n> 소요시간 : 90분\n> 장소: 강남구청역 2번 출구 인근\n> 7세 유치원생, 남녀 초등학생 1-6학년\n> 부모 동반, 좌담회는 어린이만 참석\n> 사례비: 7만원\n* 유치원(7세), 초등학교 1~6학년 남자 / 여자아이\n* 활발하며 본인의 생각을 조리 있게 말할 수 있는 아이\n* 부모님과 동반하나 좌담회는 아이만 참석\n* 감염병(독감 등) 문제 없는 분\n※ 대중교통 이용\n< 신청시 기재 사항 >\n1. 부모님 - 이름 / 성별/ 나이 (주민번호 앞자리) / 거주구/ 연락처 / 자녀 성별 및 나이\n2. 참석 어린이 - 이름/ 성별/ 생년월 (예시) 2020년 05월 / 학교 학년\n3. 평소 즐기는 놀이 3가지\n4. 보호자 통화 가능 시간 (5분내외 소요)\n아이와 통화 가능한 시간 (2-3분 소요)\nhttps://forms.gle/Q8wEXWvCSxqNZzdn7\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.14. 20:31 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n9월~10월) 2026 콘텐츠산업 노동환경 _FGI -남성\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n10/12~15) 7세 유치원~ 남녀 초등학생(1-3학년) 대면 좌담회\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n고유링크) 급급급) 14세 이상, 중/고등학생 한국거주 남학생 ) 게임 사용자 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n고유링크) 급급급) 14세 이상, 중/고등학생 한국거주 여학생 ) 게임 사용자 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
