      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 18~24세 남녀/ 25세이상 남녀 ) 생성형 AI 대규모 커뮤니티 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.14. 18:09\n조회 49\n구독\n고유링크) 18~24세 남녀/ 25세이상 남녀 ) 생성형 AI 대규모 커뮤니티 조사\nAI 커뮤니티 회원을 이번 주에는 중간 연령대도 모집 진행하기로 해서, 이번 주 금요일까지 다음과 같이 신청 요청드립니다.\nl 모집 인원 수: 100명\nl 연령대:\n일별\n주간\n18-24세\n10\n50\n25세 이상\n10\n50\n합계\n20\n100\n학생도 일부 모집되도록 부탁드립니다\n신청하신분은 재신청 안하셔도 됩니다\n6개월 이상 가능하신분만 신청해주세요~\n성 (남/여), 스마트폰 운영체제(안드로이드/iOS) 쿼터 없음\n1. 신청링크 : 해당 링크는 송난주 소개자님의 고유한 링크입니다.\n· https://kon.kric.com/project/2601012_C/INDEX.asp\n선정방법\n1) 신청링크로 1차 스크리닝 (성, 연령, 직업, 휴대폰 종류)\n2) 고객사 링크 간단한 확인 문항(10분 소요)\n3) 구글계정으로 최종 초대장 발송 -> 참여 확정\n좋아요\n0\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.14. 20:06 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n9/15 ~ 10/3- 20-59세 남/여)삼성 AI 제트(400W) 무선청소기 관련 가구방문 인터뷰\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n고유링크) 18~24세 남녀/ 25세이상 남녀 ) 생성형 AI 대규모 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n10/13~15) 간편식 패키지관련 설문조사\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n만나이 19~45세 여성 (2007~1980년생) 간식 맛 테스트 갱조사\n좌담회알바좌담회카페\n26.09.14.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
